<?php $pageTitle = 'Log Referral'; $breadcrumb = 'Referral / Log'; ob_start(); ?><div class="card"><div class="card-header"><h2 class="card-title">Log Push dan Webhook</h2><div><a class="btn btn-secondary" href="<?php echo APP_URL; ?>/referral/logs?type=all">Semua</a> <a class="btn btn-secondary" href="<?php echo APP_URL; ?>/referral/logs?type=push">Push</a> <a class="btn btn-secondary" href="<?php echo APP_URL; ?>/referral/logs?type=webhook">Webhook</a></div></div><div class="card-body"><?php if ($type !== 'webhook'): ?><h3>Push terbaru</h3><table class="table"><thead><tr><th>Waktu</th><th>Staff</th><th>HTTP</th><th>Hasil</th><th>Error</th></tr></thead><tbody><?php foreach ($pushLogs as $log): ?><tr><td><?php echo htmlspecialchars($log['created_at']); ?></td><td><?php echo htmlspecialchars($log['staff_name']); ?></td><td><?php echo (int) $log['http_status']; ?></td><td><?php echo $log['success'] ? 'Sukses' : 'Gagal'; ?></td><td><?php echo htmlspecialchars($log['error_message'] ?: '-'); ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?><?php if ($type !== 'push'): ?><h3>Webhook terbaru</h3><table class="table"><thead><tr><th>Waktu</th><th>Event</th><th>Kode</th><th>Signature</th><th>Diproses</th><th>Error</th></tr></thead><tbody><?php foreach ($webhookLogs as $log): ?><tr><td><?php echo htmlspecialchars($log['created_at']); ?></td><td><?php echo htmlspecialchars($log['event_type'] ?: '-'); ?></td><td><?php echo htmlspecialchars($log['referral_code'] ?: '-'); ?></td><td><?php echo $log['signature_valid'] ? 'Valid' : 'Invalid'; ?></td><td><?php echo $log['processed'] ? 'Ya' : 'Tidak'; ?></td><td><?php echo htmlspecialchars($log['error_message'] ?: '-'); ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div></div><?php $content = ob_get_clean(); include __DIR__ . '/../layouts/main.php'; ?>